public int minDeletionSize(String[] strs) {
    int n = strs.length;
    int m = strs[0].length();
    int[] dp = new int[m];
    int maxKept = 0;

    for (int i = 0; i < m; i++) {
        dp[i] = 1;
        for (int j = 0; j < i; j++) {
            if (canAppend(strs, j, i)) {
                dp[i] = Math.max(dp[i], dp[j] + 1);
            }
        }
        maxKept = Math.max(maxKept, dp[i]);
    }

    return m - maxKept;
}
